function trackV(){var L=orders.filter(o=>o.status=="pending"||ACTIVE.includes(o.status)).sort(byTime);return L.map(o=>{var min=Math.floor((Date.now()/1000-secs(o))/60);return '<div class="card stack"><div class="row"><b>#'+oid(o)+' · '+esc(o.name)+'</b><span class="vb w">'+min+' min</span></div>'+stageBar(o)+'<div class="mu s2">'+(o.riderName?"🛵 "+esc(o.riderName):"No rider yet")+' · '+money(fin(o))+'</div></div>'}).join("")||'<p class="mu">No live orders right now.</p>'}
/* baskets & dispatch */
function hav(a,b){var R=6371,p=Math.PI/180,dl=(b.lat-a.lat)*p,dg=(b.lng-a.lng)*p,x=Math.sin(dl/2)*Math.sin(dl/2)+Math.cos(a.lat*p)*Math.cos(b.lat*p)*Math.sin(dg/2)*Math.sin(dg/2);return 2*R*Math.asin(Math.sqrt(x))}
var near=(a,b)=>a.lat!=null&&b.lat!=null&&a.lng!=null&&b.lng!=null&&hav(a,b)<=(+dsp.radiusKm||1);
function baskets(){var P=orders.filter(o=>o.status=="pending").sort((a,b)=>secs(a)-secs(b)),B=[];P.forEach(o=>{var b=B.filter(x=>x.list.length<(+dsp.maxOrders||5)&&x.list.some(y=>near(y,o)))[0];if(b)b.list.push(o);else B.push({list:[o],t0:secs(o)})});return B}
var bReady=b=>b.list.length>=(+dsp.maxOrders||5)||Date.now()/1000-b.t0>=(+dsp.waitMin||30)*60;
var bLeft=b=>Math.max(0,Math.ceil(((+dsp.waitMin||30)*60-(Date.now()/1000-b.t0))/60));
var load=r=>orders.filter(o=>o.riderId==r.id&&ACTIVE.includes(o.status)).length;
function pickRider(n){return riders.filter(r=>r.approved&&r.available&&load(r)+n<=(+dsp.maxOrders||5)).sort((a,b)=>load(a)-load(b))[0]}
async function assignList(list,r,eta){var b=db.batch();list.forEach(o=>b.update(db.collection("orders").doc(o.id),{riderId:r.id,riderName:r.name,status:"assigned",assignedAt:TS(),eta:+eta||20,etaAt:Date.now()}));await b.commit()}
async function autoNow(quiet){var n=0;for(var b of baskets()){if(!bReady(b))continue;var r=pickRider(b.list.length);if(!r)continue;try{await assignList(b.list,r,dsp.eta);n++}catch(e){}}if(!quiet)toast(n?n+" basket(s) assigned":"Nothing ready to assign");return n}
function bkAssign(i){var b=baskets()[i];if(!b)return;var r=riders.find(x=>x.id==document.getElementById("bk"+i).value);if(!r)return alert("Choose a rider");assignList(b.list,r,dsp.eta).then(()=>toast("Basket assigned to "+r.name)).catch(e=>alert(e.message))}
function saveDsp(){var v=id=>+document.getElementById(id).value;db.collection("settings").doc("dispatch").set({waitMin:v("dw")||30,radiusKm:v("dr")||1,maxOrders:v("dm")||5,eta:v("de")||20,auto:document.getElementById("da").checked},{merge:true}).then(()=>toast("Saved")).catch(e=>alert(e.message))}
function baskV(){var B=baskets(),opts=riders.filter(r=>r.approved).map(r=>'<option value="'+r.id+'">'+esc(r.name)+' ('+(r.available?"online":"offline")+' · '+load(r)+' active)</option>').join("");
return '<div class="card stack"><b>⚙️ Auto-assignment rules</b><div class="row"><span class="mu">Wait for nearby orders (min)</span><input id="dw" type="number" style="width:90px" value="'+(dsp.waitMin||30)+'"></div><div class="row"><span class="mu">Basket radius (km)</span><input id="dr" type="number" style="width:90px" value="'+(dsp.radiusKm||1)+'"></div><div class="row"><span class="mu">Max orders per rider</span><input id="dm" type="number" style="width:90px" value="'+(dsp.maxOrders||5)+'"></div><div class="row"><span class="mu">Default delivery time (min)</span><input id="de" type="number" style="width:90px" value="'+(dsp.eta||20)+'"></div><label class="row"><span>Auto-assign to an active rider</span><input id="da" type="checkbox" style="width:auto" '+(dsp.auto?"checked":"")+'></label><button class="b w" onclick="saveDsp()">Save rules</button><button class="b l w" onclick="autoNow()">▶ Run auto-assign now</button><div class="mu s2">With Blaze, the server runs this every minute even when the admin app is closed.</div></div><h2>🧺 Order baskets ('+B.length+')</h2>'+
(B.map((b,i)=>'<div class="card stack"><div class="row"><b>'+b.list.length+' order'+(b.list.length>1?"s":"")+' within '+(dsp.radiusKm||1)+' km</b><span class="vb '+(bReady(b)?"":"w")+'">'+(bReady(b)?"Ready":bLeft(b)+" min left")+'</span></div>'+b.list.map(o=>'<div class="mu s2">#'+oid(o)+' · '+esc(o.name)+' · '+esc(o.addr)+'</div>').join("")+'<div class="row"><select id="bk'+i+'" style="flex:1">'+opts+'</select><button class="b" onclick="bkAssign('+i+')">Assign basket</button></div></div>').join("")||'<p class="mu">No pending orders waiting.</p>')}
/* cancel & refund */
var CRL2={not_responding:"Not responding call",customer_cancel:"Customer cancelled",rider_problem:"Rider problem"},RS2={missing:"Missing",damage:"Damaged",customer_cancel:"Customer cancelled"};
function refAmt(o){if(o.refund)return 0;if(o.status=="cancelled")return o.pay=="upi"||o.paid?o.total:0;if(o.status=="delivered"&&o.finalTotal!=null&&o.pay=="upi")return Math.max(0,o.total-o.finalTotal);return 0}
function cancV(){var L=orders.filter(o=>o.status=="cancelled"||(o.status=="delivered"&&o.finalTotal!=null&&o.finalTotal<o.total)).sort(byTime);
return L.map(o=>{var a=refAmt(o),why=o.status=="cancelled"?(CRL2[o.cancelReason]||"Cancelled"):Object.keys(o.flags||{}).map(k=>esc(o.items[k]?o.items[k].name:"")+" — "+(RS2[o.flags[k]]||"")).join("<br>");
return '<div class="card stack"><div class="row"><b>#'+oid(o)+' · '+esc(o.name)+'</b><span class="vb '+(o.status=="cancelled"?"r":"w")+'">'+(o.status=="cancelled"?"Cancelled":"Partial")+'</span></div><div class="mu s2">'+dt(o)+' · '+(o.pay=="upi"?"UPI":"COD")+'</div><div class="mu">'+why+'</div>'+(o.refund?'<div class="vb">Refunded '+money(o.refund.amt)+' to wallet</div>':a?'<button class="b w" onclick="refund(\''+o.id+'\')">💸 Refund '+money(a)+' to wallet</button>':'<div class="mu s2">No refund needed ('+(o.pay=="upi"?"already refunded":"cash order")+')</div>')+'</div>'}).join("")||'<p class="mu">No cancelled orders.</p>'}
function refund(id){var o=orders.find(x=>x.id==id),a=refAmt(o);if(!a)return;ask("Refund "+money(a)+" to "+o.name+"'s wallet?",async function(){try{await db.runTransaction(async t=>{var ur=db.collection("users").doc(o.uid),us=await t.get(ur);t.update(ur,{wallet:(us.data().wallet||0)+a});t.set(ur.collection("wallet").doc(),{amt:a,type:"refund",note:"Refund for order #"+oid(o),at:Date.now(),by:me.uid});t.update(db.collection("orders").doc(id),{refund:{amt:a,at:Date.now(),by:me.uid}})});toast("Refunded "+money(a))}catch(e){alert(e.message)}},"Refund")}
/* ================= 4. INVENTORY & CATALOG ================= */
var stPill=p=>p.stock<=0?'<span class="vb r">Out of stock</span>':p.stock<=LOW?'<span class="vb w">Low · '+p.stock+'</span>':'<span class="vb">In stock · '+p.stock+'</span>';
function pS(v){inv=v;var e=document.getElementById("plist");if(e)e.innerHTML=plistH()}
var pq="";
function plistH(){var q=pq.trim().toLowerCase(),L=products.filter(p=>(!q||p.name.toLowerCase().indexOf(q)>=0)&&(inv=="all"||(inv=="low"&&p.stock>0&&p.stock<=LOW)||(inv=="out"&&p.stock<=0)));
return L.map(p=>'<div class="card stack"><div class="row" style="justify-content:flex-start;gap:12px"><div class="pimg">'+img(p)+'</div><div style="flex:1;min-width:0"><b>'+esc(p.name)+'</b><div class="mu s2">'+money(p.price)+(p.mrp>p.price?' <s>'+money(p.mrp)+'</s>':'')+' · '+esc(p.cat||"No category")+'</div>'+stPill(p)+'</div></div><div class="hs">'+SECS.map(x=>'<button class="chip '+(inSec(p,x[0])?"on":"")+'" onclick="tg(\''+p.id+'\',\''+x[0]+'\')">'+x[1]+'</button>').join("")+'</div><div class="row" style="gap:8px"><select style="flex:1" onchange="setCatP(\''+p.id+'\',this.value)"><option value="">Category</option>'+CATS.map(c=>'<option '+(p.cat==c[0]?"selected":"")+'>'+esc(c[0])+'</option>').join("")+'</select></div><div class="row" style="gap:8px"><button class="b l" style="flex:1" onclick="editProd(\''+p.id+'\')">✏️ Edit</button><button class="b l" style="flex:1" onclick="setPimg(\''+p.id+'\')">📷 Photo</button><button class="b l" style="flex:1" onclick="delP(\''+p.id+'\')">🗑</button></div></div>').join("")||'<p class="mu">No products found.</p>'}
function productsV(){var low=products.filter(p=>p.stock>0&&p.stock<=LOW).length,out=products.filter(p=>p.stock<=0).length;
return '<div class="kp"><div><b>'+products.length+'</b><span>Products</span></div><div><b style="color:#b45309">'+low+'</b><span>Low stock</span></div><div><b style="color:#b3261e">'+out+'</b><span>Out of stock</span></div></div><button class="cta" style="margin:0 0 10px" onclick="addOpen=!addOpen;render(true)">'+(addOpen?"Close form":"+ Add product")+'</button>'+(addOpen?prodForm():"")+'<div class="hs">'+[["all","All"],["low","Low stock"],["out","Out of stock"]].map(f=>'<button class="chip '+(inv==f[0]?"on":"")+'" onclick="inv=\''+f[0]+'\';render(true)">'+f[1]+'</button>').join("")+'</div><input class="srch" placeholder="Search products" value="'+esc(pq)+'" oninput="pq=this.value;pS(inv)"><div id="plist">'+plistH()+'</div>'}
function lowV(){var L=products.filter(p=>p.stock<=LOW).sort((a,b)=>a.stock-b.stock);return L.map(p=>'<div class="card stack"><div class="row"><b>'+esc(p.name)+'</b>'+stPill(p)+'</div><div class="row" style="gap:8px"><button class="b l" style="flex:1" onclick="addStock(\''+p.id+'\',10)">+10</button><button class="b l" style="flex:1" onclick="addStock(\''+p.id+'\',50)">+50</button><button class="b" style="flex:1" onclick="stk(\''+p.id+'\')">Set</button></div></div>').join("")||'<p class="mu">Everything is well stocked 🎉</p>'}
function addStock(id,n){var p=products.find(x=>x.id==id);db.collection("products").doc(id).update({stock:(+p.stock||0)+n}).then(()=>toast("Stock updated"))}
window.delP=function(id){ask("Delete this product? Its photo will also be removed from Cloudinary.",function(){db.collection("products").doc(id).delete().catch(e=>alert(e.message))},"Delete")};
window.stk=function(id){var p=products.find(x=>x.id==id);askIn("Set stock",[{l:"New stock quantity",t:"number",v:p.stock}],function(v){if(isNaN(+v[0]))return;db.collection("products").doc(id).update({stock:+v[0]})})};
window.editProd=function(id){var p=products.find(x=>x.id==id);askIn("Edit product",[{l:"Name",v:p.name},{l:"Price (₹)",t:"number",v:p.price},{l:"MRP (₹, optional)",t:"number",v:p.mrp||""},{l:"Stock",t:"number",v:p.stock}],function(v){db.collection("products").doc(id).update({name:v[0].trim()||p.name,price:+v[1]||p.price,mrp:+v[2]||null,stock:+v[3]||0}).catch(e=>alert(e.message))})};
/* ================= 5. RIDERS ================= */
var KYN={aadhaar:"Aadhaar (NID)",pan:"PAN card",dl:"Driving licence",selfie:"Selfie"};
window.ridV=function(){return riders.map(r=>{var m=orders.filter(o=>o.riderId==r.id),a=m.filter(o=>ACTIVE.includes(o.status)).length,d=m.filter(o=>o.status=="delivered").length,cod=m.filter(o=>o.status=="delivered"&&o.pay=="cod").reduce((s,o)=>s+fin(o),0),dep=deps.filter(x=>x.riderId==r.id&&x.status!=="pending"&&x.status!=="rejected").reduce((s,x)=>s+(+x.amount||0),0),dv=r.docVerified||{},st=r.approved?(!r.available?"Offline":busy(r)?"Busy":"Online"):(r.kyc=="submitted"?"KYC submitted":"Docs pending");
return '<div class="card stack"><div class="row" style="justify-content:flex-start;gap:12px"><div class="pimg">'+(r.photo?'<img src="'+esc(r.photo)+'" style="width:100%;height:100%;border-radius:14px;object-fit:cover">':"🛵")+'</div><div style="flex:1;min-width:0"><b>'+esc(r.name)+'</b> <span class="mu s2">'+esc(r.riderCode||"")+'</span><div class="mu s2"><a href="tel:'+esc(r.phone)+'">'+esc(r.phone)+'</a> · '+esc(r.city||"")+'</div></div><span class="vb '+(r.approved?"":"w")+'">'+st+'</span></div><div class="mu s2">Active '+a+' · Delivered '+d+(r.approved?' · Cash held '+money(Math.max(0,cod-dep)):'')+'</div><div class="hs">'+["aadhaar","pan","dl"].map(k=>'<span class="vb '+(dv[k]?"":"w")+'">'+(dv[k]?"✔ ":"")+(KYN[k])+'</span>').join("")+'</div><div class="row" style="gap:8px"><button class="b l" style="flex:1" onclick="viewKyc(\''+r.id+'\')">📄 Documents</button>'+(r.approved?'<button class="b l" style="flex:1" onclick="deposit(\''+r.id+'\')">💵 Deposit</button><button class="b l" style="flex:1" onclick="appr(\''+r.id+'\',false)">Revoke</button>':'<button class="b" style="flex:1" onclick="approve(\''+r.id+'\')">Approve</button>')+'</div></div>'}).join("")||'<p class="mu">No riders yet.</p>'};
window.viewKyc=async function(id){try{var r=riders.find(x=>x.id==id),s=await db.collection("users").doc(id).collection("kyc").get(),dv=r.docVerified||{},h='<h2>'+esc(r.name)+'</h2><div class="mu s2" style="margin-bottom:8px">DOB '+esc(r.dob||"-")+' · City '+esc(r.city||"-")+' · DL '+esc(r.dl||"-")+'</div>';
s.forEach(d=>{h+='<div class="card stack"><div class="row"><b>'+esc(KYN[d.id]||d.id)+'</b><span class="vb '+(dv[d.id]?"":"w")+'">'+(dv[d.id]?"✔ Verified":"Pending")+'</span></div><img src="'+esc(d.data().img)+'" style="width:100%;height:auto;border-radius:10px"><button class="b '+(dv[d.id]?"l":"")+' w" onclick="dverify(\''+id+'\',\''+d.id+'\','+!dv[d.id]+')">'+(dv[d.id]?"Remove verification":"Mark as verified")+'</button></div>'});
if(!s.size)h+='<p class="mu">No documents uploaded.</p>';var b=r.bank;if(b)h+='<div class="card"><b>🏦 Bank</b><div class="mu">'+esc(b.name)+'<br>A/C '+esc(b.acc)+'<br>'+esc(b.bank)+' · '+esc(b.ifsc)+'</div></div>';pop(h)}catch(e){alert(e.message)}};
function dverify(id,k,v){var u={};u["docVerified."+k]=v;db.collection("users").doc(id).update(u).then(()=>viewKyc(id)).catch(e=>alert(e.message))}
window.approve=async function(id){var r=riders.find(x=>x.id==id);var go=async function(){try{await db.runTransaction(async t=>{var cr=db.collection("counters").doc("rider"),c=await t.get(cr),n=(c.exists?c.data().n:0)+1;t.set(cr,{n:n});t.update(db.collection("users").doc(id),{approved:true,riderCode:r.riderCode||"KOL_KB_"+String(n).padStart(4,"0")})});toast("Rider approved")}catch(e){alert(e.message)}};if(r.kyc!="submitted")ask("This rider has not submitted documents. Approve anyway?",go,"Approve");else go()};
window.deposit=function(id){askIn("Record cash deposit",[{l:"Cash deposited by rider (₹)",t:"number"}],function(v){if(!(+v[0]>0))return;db.collection("deposits").add({riderId:id,amount:+v[0],at:Date.now()}).then(()=>toast("Deposit recorded")).catch(e=>alert(e.message))},"Record")};
window.depNo=function(id){ask("Reject this deposit request?",function(){db.collection("deposits").doc(id).update({status:"rejected"}).catch(e=>alert(e.message))},"Reject")};
window.delMedia=function(id){ask("Delete this image? It will also be removed from Cloudinary.",function(){db.collection("riderMedia").doc(id).delete().catch(e=>alert(e.message))},"Delete")};
/* live GPS map */
function loadLeaflet(cb){if(window.L){cb();return}var c=document.createElement("link");c.rel="stylesheet";c.href="https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/leaflet.css";document.head.appendChild(c);var s=document.createElement("script");s.src="https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/leaflet.js";s.onload=cb;document.head.appendChild(s)}
var MAP=null,MK=[];
function mapV(){return '<div class="card"><b>📡 Live rider locations</b><div class="mu s2">Online riders appear here while their app shares location.</div></div><div id="lmap" style="height:62vh;border-radius:18px;overflow:hidden"></div>'}
function drawMap(){loadLeaflet(function(){var el=document.getElementById("lmap");if(!el)return;if(!MAP||MAP._container!==el){if(MAP){try{MAP.remove()}catch(e){}}MAP=L.map(el).setView([22.57,88.36],12);L.tileLayer("https://tile.openstreetmap.org/{z}/{x}/{y}.png",{maxZoom:19,attribution:"© OpenStreetMap"}).addTo(MAP)}
MK.forEach(m=>m.remove());MK=[];var pts=[];function pin(lat,lng,e,tip){var m=L.marker([lat,lng],{icon:L.divIcon({className:"",html:'<div style="font-size:26px">'+e+'</div>',iconSize:[30,30]})}).addTo(MAP).bindPopup(tip);MK.push(m);pts.push([lat,lng])}
if(cfgR.storeLoc){var p=cfgR.storeLoc.split(",");if(!isNaN(+p[0]))pin(+p[0],+p[1],"🏪",esc(cfgR.storeName||STORE))}
riders.forEach(r=>{if(r.loc&&r.approved&&(r.available||Date.now()-r.loc.at<600000))pin(r.loc.lat,r.loc.lng,"🛵",esc(r.name)+" · "+(r.available?"online":"offline")+"<br>"+Math.round((Date.now()-r.loc.at)/60000)+" min ago")});
orders.filter(o=>ACTIVE.includes(o.status)&&o.lat!=null).forEach(o=>pin(o.lat,o.lng,"📍","#"+oid(o)+" · "+esc(o.name)));
if(pts.length)MAP.fitBounds(pts,{padding:[40,40],maxZoom:15})})}
/* payout & commission */
var monthKey=()=>{var d=new Date();return d.getFullYear()+"-"+String(d.getMonth()+1).padStart(2,"0")};
function riderKm(o){var p=(cfgR.storeLoc||"").split(",");if(o.lat==null||p.length<2||isNaN(+p[0]))return 0;return hav({lat:+p[0],lng:+p[1]},{lat:o.lat,lng:o.lng})}
function payV(){var m=monthKey(),n=new Date(),t0=new Date(n.getFullYear(),n.getMonth(),1).getTime()/1000;
return '<div class="card"><b>💼 Payout & commission</b><div class="mu s2">Set a fixed salary and/or a rate per order and per km for each rider. Month '+m+'.</div></div>'+riders.filter(r=>r.approved).map(r=>{var p=r.pay||{},ds=orders.filter(o=>o.riderId==r.id&&o.status=="delivered"&&o.deliveredAt&&o.deliveredAt.seconds>=t0),earn=ds.reduce((s,o)=>s+(o.earn||0),0),km=ds.reduce((s,o)=>s+riderKm(o),0),total=earn+(+p.fixed||0),pd=payouts.filter(x=>x.riderId==r.id&&x.month==m)[0];
return '<div class="card stack"><b>'+esc(r.name)+' <span class="mu s2">'+esc(r.riderCode||"")+'</span></b><div class="row" style="gap:8px"><div style="flex:1"><div class="mu s2">Fixed / month</div><input id="pf'+r.id+'" type="number" value="'+(p.fixed||"")+'"></div><div style="flex:1"><div class="mu s2">Per order</div><input id="po'+r.id+'" type="number" value="'+(p.perOrder==null?"":p.perOrder)+'"></div><div style="flex:1"><div class="mu s2">Per km</div><input id="pk'+r.id+'" type="number" value="'+(p.perKm||"")+'"></div></div><button class="b l w" onclick="savePay(\''+r.id+'\')">Save rates</button><div class="mu s2">This month: '+ds.length+' orders · '+km.toFixed(1)+' km · earnings '+money(earn)+'</div><div class="row"><b>Payable '+money(total)+'</b>'+(pd?'<span class="vb">Paid '+money(pd.amount)+'</span>':'<button class="b" onclick="markPaid(\''+r.id+'\','+Math.round(total)+')">Mark paid</button>')+'</div></div>'}).join("")}
function savePay(id){var g=k=>document.getElementById(k+id).value;db.collection("users").doc(id).update({pay:{fixed:+g("pf")||0,perOrder:g("po")===""?null:+g("po"),perKm:+g("pk")||0}}).then(()=>toast("Rates saved")).catch(e=>alert(e.message))}
function markPaid(id,amt){ask("Mark "+money(amt)+" as paid for this month?",function(){db.collection("payouts").add({riderId:id,month:monthKey(),amount:amt,at:Date.now(),by:me.uid}).then(()=>toast("Marked paid"))},"Mark paid")}
/* ================= 6. CUSTOMERS ================= */
function cStats(c){var os=orders.filter(o=>o.uid==c.id),can=os.filter(o=>o.status=="cancelled"&&(o.cancelReason=="customer_cancel"||o.cancelReason=="not_responding")).length,comp=os.filter(o=>o.flags&&Object.keys(o.flags).some(k=>o.flags[k]=="damage"||o.flags[k]=="missing")).length+tickets.filter(t=>t.who=="customer"&&t.riderId==c.id&&(t.type=="missing"||t.type=="damage")).length;
return{n:os.length,spent:os.filter(o=>o.status=="delivered").reduce((s,o)=>s+fin(o),0),can:can,comp:comp,risky:can>=3||comp>=3}}
function cS(v){cuq=v;var e=document.getElementById("clist");if(e)e.innerHTML=custListH()}
function custListH(){var q=cuq.trim().toLowerCase(),L=custs.filter(c=>!q||(c.name||"").toLowerCase().indexOf(q)>=0||(c.phone||"").indexOf(q)>=0||(c.email||"").toLowerCase().indexOf(q)>=0).map(c=>({c:c,s:cStats(c)})).sort((a,b)=>(b.s.risky-a.s.risky)||b.s.n-a.s.n);
return L.map(x=>{var c=x.c,s=x.s;return '<div class="card stack"><div class="row"><b>'+esc(c.name)+'</b>'+(c.blocked?'<span class="vb r">Blocked</span>':s.risky?'<span class="vb w">⚠ Risky</span>':'<span class="vb">Active</span>')+'</div><div class="mu s2">📞 '+esc(c.phone)+' · ✉️ '+esc(c.email||"")+'</div><div class="mu s2">📍 '+esc(c.addr||"No saved address")+'</div><div class="mu s2">'+s.n+' orders · '+money(s.spent)+' spent · '+s.can+' cancels · '+s.comp+' damage/missing complaints · wallet '+money(c.wallet)+'</div><div class="row" style="gap:8px"><button class="b l" style="flex:1" onclick="custHist(\''+c.id+'\')">🧾 Orders</button><button class="b l" style="flex:1" onclick="walletForm(\''+c.id+'\')">👛 Wallet</button><button class="b '+(c.blocked?"":"l")+'" style="flex:1" onclick="blockC(\''+c.id+'\','+!c.blocked+')">'+(c.blocked?"Unblock":"🚫 Block")+'</button></div></div>'}).join("")||'<p class="mu">No customers found.</p>'}
function usersV(){var risky=custs.filter(c=>cStats(c).risky).length;return '<div class="kp"><div><b>'+custs.length+'</b><span>Customers</span></div><div><b style="color:#b45309">'+risky+'</b><span>Risky</span></div><div><b style="color:#b3261e">'+custs.filter(c=>c.blocked).length+'</b><span>Blocked</span></div></div><input class="srch" placeholder="Search name, phone or email" value="'+esc(cuq)+'" oninput="cS(this.value)"><div id="clist">'+custListH()+'</div>'}
function blockC(id,v){var c=custs.find(x=>x.id==id);ask((v?"Block ":"Unblock ")+c.name+"?",function(){db.collection("users").doc(id).update({blocked:v}).then(()=>toast(v?"Blocked":"Unblocked")).catch(e=>alert(e.message))},v?"Block":"Unblock")}
function custHist(id){var c=custs.find(x=>x.id==id),L=orders.filter(o=>o.uid==id).sort(byTime);pop('<h2>'+esc(c.name)+'</h2>'+(L.map(o=>'<div class="card row"><span><b>#'+oid(o)+'</b><div class="mu s2">'+dt(o)+'</div></span><span style="text-align:right">'+money(fin(o))+'<div class="mu s2">'+(ST[o.status]||o.status)+'</div></span></div>').join("")||'<p class="mu">No orders.</p>'))}
function walletForm(id){var c=custs.find(x=>x.id==id);mpop('<div class="mh"><div class="mi2">👛</div><h2>'+esc(c.name)+'</h2><div class="mu">Balance '+money(c.wallet)+'</div></div><input id="wa" type="number" placeholder="Amount (₹)"><input id="wn" placeholder="Note (e.g. promo credit)"><div class="row" style="gap:8px;margin-top:6px"><button class="b" style="flex:1" onclick="walletTx(\''+id+'\',1)">➕ Add</button><button class="b l" style="flex:1" onclick="walletTx(\''+id+'\',-1)">➖ Deduct</button></div><button class="b l w" style="margin-top:8px" onclick="walletHistA(\''+id+'\')">History</button>')}
function walletTx(id,sign){var a=Math.round(+document.getElementById("wa").value),note=document.getElementById("wn").value.trim();if(!(a>0))return alert("Enter an amount");
db.runTransaction(async t=>{var ur=db.collection("users").doc(id),us=await t.get(ur),bal=us.data().wallet||0;if(sign<0&&a>bal)throw new Error("Balance is only "+money(bal));t.update(ur,{wallet:bal+sign*a});t.set(ur.collection("wallet").doc(),{amt:sign*a,type:sign>0?"credit":"debit",note:note||(sign>0?"Added by admin":"Deducted by admin"),at:Date.now(),by:me.uid})}).then(()=>{hidePop();toast("Wallet updated")}).catch(e=>alert(e.message))}
async function walletHistA(id){try{var s=await db.collection("users").doc(id).collection("wallet").orderBy("at","desc").limit(30).get(),h='<h2>Wallet history</h2>';s.forEach(d=>{var x=d.data();h+='<div class="card row"><span>'+esc(x.note||x.type)+'<div class="mu s2">'+tmF(x.at)+'</div></span><b style="color:'+(x.amt<0?"#b3261e":"#12703f")+'">'+(x.amt<0?"-":"+")+money(Math.abs(x.amt))+'</b></div>'});if(!s.size)h+='<p class="mu">No history yet.</p>';pop(h)}catch(e){alert(e.message)}}
function walletV(){var L=custs.slice().sort((a,b)=>(b.wallet||0)-(a.wallet||0));return '<div class="card"><b>👛 Customer wallets</b><div class="mu s2">Add or deduct balance. Every change is saved in the history and customers see it in the app.</div></div>'+L.map(c=>'<div class="card row" onclick="walletForm(\''+c.id+'\')"><span><b>'+esc(c.name)+'</b><div class="mu s2">'+esc(c.phone)+'</div></span><b>'+money(c.wallet)+' ›</b></div>').join("")}
