function sendP(){var t=document.getElementById("nti").value.trim(),b=document.getElementById("nb").value.trim(),k=document.getElementById("nk").value;if(!t||!b)return alert("Enter a title and a message");ask("Send this notification now?",function(){db.collection("broadcasts").add({to:document.getElementById("nt").value,title:k+t,body:b,at:Date.now()}).then(()=>{toast("Sent");render(true)}).catch(e=>alert(e.message))},"Send")}
function targetList(){var now=Date.now()/1000,res=[],a=(targ.area||"").trim().toLowerCase();custs.forEach(c=>{if(c.blocked)return;if(targ.kind=="inactive"){var last=orders.filter(o=>o.uid==c.id).reduce((m,o)=>Math.max(m,secs(o)),0);if(!last||now-last>targ.days*86400)res.push(c)}else if(a&&((c.addr||"").toLowerCase().indexOf(a)>=0||orders.some(o=>o.uid==c.id&&(o.addr||"").toLowerCase().indexOf(a)>=0)))res.push(c)});return res}
function targetV(){var L=targetList();return '<div class="card stack"><b>🎯 Targeted notification</b><div class="hs">'+[["inactive",7,"No order 7 days"],["inactive",15,"No order 15 days"],["inactive",30,"No order 30 days"],["area",0,"By area"]].map(f=>'<button class="chip '+(targ.kind==f[0]&&(f[0]=="area"||targ.days==f[1])?"on":"")+'" onclick="targ.kind=\''+f[0]+'\';targ.days='+f[1]+';render(true)">'+f[2]+'</button>').join("")+'</div>'+(targ.kind=="area"?'<input id="tarea" placeholder="Area / pincode / landmark in the address" value="'+esc(targ.area)+'" oninput="targ.area=this.value">':'')+'<div class="vb">'+L.length+' customer'+(L.length==1?"":"s")+' match</div><input id="tti" placeholder="Title"><input id="tbd" placeholder="Message"><button class="b w" onclick="sendT()">Send to '+L.length+'</button></div>'}
function sendT(){var L=targetList().slice(0,450),t=document.getElementById("tti").value.trim(),b=document.getElementById("tbd").value.trim();if(!L.length)return alert("No customers match");if(!t||!b)return alert("Enter a title and a message");ask("Send to "+L.length+" customers?",function(){db.collection("broadcasts").add({to:"uids",uids:L.map(c=>c.id),title:t,body:b,at:Date.now()}).then(()=>toast("Sent to "+L.length)).catch(e=>alert(e.message))},"Send")}
function couponsV(){return '<div class="card stack"><b>🏷️ New coupon / promo code</b><input id="cpc" placeholder="CODE (e.g. SAVE50)"><select id="cpk"><option value="flat">Flat ₹ off</option><option value="percent">Percent % off</option><option value="freedel">Free delivery</option></select><input id="cpv" type="number" placeholder="Discount value (₹ or %)"><input id="cpm" type="number" placeholder="Minimum order value (₹)"><input id="cpx" type="number" placeholder="Max discount ₹ (for percent)"><input id="cpl" type="number" placeholder="Total uses limit"><input id="cpu" type="number" placeholder="Uses per customer (default 1)"><label class="mu s2">Expires on</label><input id="cpe" type="date"><button class="b w" onclick="saveCoupon()">Create coupon</button></div><h2>Coupons</h2>'+coupons.map(c=>'<div class="card stack"><div class="row"><b>'+esc(c.id)+'</b><span class="vb '+(c.active?"":"w")+'">'+(c.active?"Active":"Paused")+'</span></div><div class="mu s2">'+(c.kind=="percent"?c.value+"% off":c.kind=="freedel"?"Free delivery":"₹"+c.value+" off")+' · min '+money(c.minOrder)+(c.maxDisc?' · max '+money(c.maxDisc):'')+'</div><div class="mu s2">Used '+(c.used||0)+' / '+(c.limit||"∞")+' · '+(c.perUser||1)+' per customer'+(c.expires?' · expires '+esc(c.expires):'')+'</div><div class="row" style="gap:8px"><button class="b l" style="flex:1" onclick="toggleCoupon(\''+c.id+'\','+!c.active+')">'+(c.active?"Pause":"Activate")+'</button><button class="b l" style="flex:1" onclick="delCoupon(\''+c.id+'\')">Delete</button></div></div>').join("")||'<p class="mu">No coupons yet.</p>'}
function saveCoupon(){var g=i=>document.getElementById(i).value.trim(),code=g("cpc").toUpperCase().replace(/[^A-Z0-9]/g,"");if(!code)return alert("Enter a code");var k=g("cpk"),v=+g("cpv")||0;if(k!="freedel"&&!(v>0))return alert("Enter the discount value");
db.collection("coupons").doc(code).set({kind:k,value:v,minOrder:+g("cpm")||0,maxDisc:+g("cpx")||0,limit:+g("cpl")||0,perUser:+g("cpu")||1,expires:g("cpe"),active:true,used:0,at:Date.now()}).then(()=>{toast("Coupon created");render(true)}).catch(e=>alert(e.message))}
function toggleCoupon(id,v){db.collection("coupons").doc(id).update({active:v})}
