function hbV(){return '<div class="card stack"><b>🖼️ Home page banners</b><div class="mu s2">These replace the offer banners on the customer home page. Tap a banner to open a category (optional).</div><div class="row" style="flex-wrap:wrap;justify-content:flex-start;gap:10px">'+hbn.slice().sort((a,b)=>(a.at||0)-(b.at||0)).map(b=>'<div style="position:relative"><img src="'+esc(b.img)+'" style="width:130px;height:56px;object-fit:cover;border-radius:10px"><button class="b l" style="position:absolute;top:-8px;right:-8px;padding:0 7px" onclick="delHB(\''+b.id+'\')">✕</button><div class="mu s2">'+esc(b.cat||"")+'</div></div>').join("")+'</div><button class="b w" onclick="addHB()">+ Add banner</button></div><div class="card row" onclick="nav(\'inv\',\'cats\')"><span>🏷️ <b>Category stickers</b><div class="mu s2">Change the category pictures</div></span><span class="mu">›</span></div>'}
function addHB(){if(hbn.length>=8)return alert("Maximum 8 banners");askIn("Banner link",[{l:"Open this category when tapped (exact name, optional)",p:"e.g. Dairy & Eggs"}],function(v){pickImg(900,function(d){db.collection("homeBanners").add({img:d,cat:v[0].trim(),at:Date.now()}).catch(e=>alert(e.message))})},"Choose picture")}
function delHB(id){ask("Delete this banner? It will also be removed from Cloudinary.",function(){db.collection("homeBanners").doc(id).delete()},"Delete")}
